-- Section 1821: Reading Passage 1: Stonehenge
INSERT INTO sections (id, test_id, type, title, instructions, audio_url, passage_text, order_index) VALUES
(1821, 182, 'reading', 'Reading Passage 1: Stonehenge', '<div class="ielts-reading-container"><h2 class="ielts-reading-question-section-heading">
                                            Questions 1-8                                                                                                                                                                                                    
                                                                                                                                    </h2>
                                        <div class="ielts-reading-question-section-content">
                                            <div class="ielts-reading-section-content-wrapper"><p><em>Complete the notes below.</em></p>
<p><em>Choose NO MORE THAN TWO WORDS from the passage for each answer.</em></p>
<p><em>Write your answers in boxes on your answer sheet.</em></p>
<p class="ielts-reading-passage-subhead"><strong><strong>Stonehenge</strong></strong></p>
<p><strong>Construction</strong></p>
<p>Stage 1:</p>
<ul>
<li>the ditch and henge were dug, possibly using tools made from <span class="ielts-reading-question-item"><span class="ielts-inline-input-wrap"><strong class="ielts-q-badge">1</strong><input type="text" data-qnum="1" name="question_1" class="ielts-inline-input" placeholder="[1] javob..." autocomplete="off" spellcheck="false"></span></span></li>
<li><span class="ielts-reading-question-item"><span class="ielts-inline-input-wrap"><strong class="ielts-q-badge">2</strong><input type="text" data-qnum="2" name="question_2" class="ielts-inline-input" placeholder="[2] javob..." autocomplete="off" spellcheck="false"></span></span> may have been arranged in deep pits inside the circle</li>
</ul>
<p>Stage 2:</p>
<ul>
<li>bluestones from the Preseli Hills were placed in standing position</li>
<li>theories about the transportation of the bluestones:
<ul>
<li>archaeological:
<ul>
<li>builders used <span class="ielts-reading-question-item"><span class="ielts-inline-input-wrap"><strong class="ielts-q-badge">3</strong><input type="text" data-qnum="3" name="question_3" class="ielts-inline-input" placeholder="[3] javob..." autocomplete="off" spellcheck="false"></span></span> to make sledges and rollers</li>
<li><span class="ielts-reading-question-item"><span class="ielts-inline-input-wrap"><strong class="ielts-q-badge">4</strong><input type="text" data-qnum="4" name="question_4" class="ielts-inline-input" placeholder="[4] javob..." autocomplete="off" spellcheck="false"></span></span> pulled them on giant baskets</li>
</ul>
</li>
