-- Section 1822: Reading Passage 2: Living with artificial intelligence
INSERT INTO sections (id, test_id, type, title, instructions, audio_url, passage_text, order_index) VALUES
(1822, 182, 'reading', 'Reading Passage 2: Living with artificial intelligence', '<div class="ielts-reading-container"><h2 class="ielts-reading-question-section-heading">
                                            Questions 14-19                                                                                                                                                
                                                                                                                                    </h2>
                                        <div class="ielts-reading-question-section-content">
                                            <p><em>Choose the correct letter, <strong>A</strong>, <strong>B</strong>, <strong>C</strong> or <strong>D</strong>.</em></p>
<p><em>Write the correct letter in boxes on your answer sheet.</em></p>
                                        </div>
                                        <div class="ielts-reading-questions">
                                                                                                                                                                                            <div class="ielts-standalone-q" data-qnum="14"><div class="ielts-q-header"><strong class="ielts-q-badge">14</strong><span class="ielts-q-title"><span>What point does the writer make about AI in the first paragraph?</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="14" name="question_14" value="A"><span class="ielts-radio-text"><strong>A</strong> It is difficult to predict how quickly AI will progress.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="14" name="question_14" value="B"><span class="ielts-radio-text"><strong>B</strong> Much can be learned about the use of AI in chess machines.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="14" name="question_14" value="C"><span class="ielts-radio-text"><strong>C</strong> The future is unlikely to see limitations on the capabilities of AI.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="14" name="question_14" value="D"><span class="ielts-radio-text"><strong>D</strong> Experts disagree on which specialised tasks AI will be able to perform.</span></label></div></div><div class="ielts-standalone-q" data-qnum="15"><div class="ielts-q-header"><strong class="ielts-q-badge">15</strong><span class="ielts-q-title"><span>What is the writer doing in the second paragraph?</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="15" name="question_15" value="A"><span class="ielts-radio-text"><strong>A</strong> explaining why machines will be able to outperform humans</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="15" name="question_15" value="B"><span class="ielts-radio-text"><strong>B</strong> describing the characteristics that humans and machines share</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="15" name="question_15" value="C"><span class="ielts-radio-text"><strong>C</strong> giving information about the development of machine intelligence</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="15" name="question_15" value="D"><span class="ielts-radio-text"><strong>D</strong> indicating which aspects of humans are the most advanced</span></label></div></div><div class="ielts-standalone-q" data-qnum="16"><div class="ielts-q-header"><strong class="ielts-q-badge">16</strong><span class="ielts-q-title"><span>Why does the writer mention the story of King Midas?</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="16" name="question_16" value="A"><span class="ielts-radio-text"><strong>A</strong> to compare different visions of progress</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="16" name="question_16" value="B"><span class="ielts-radio-text"><strong>B</strong> to illustrate that poorly defined objectives can go wrong</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="16" name="question_16" value="C"><span class="ielts-radio-text"><strong>C</strong> to emphasise the need for cooperation</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="16" name="question_16" value="D"><span class="ielts-radio-text"><strong>D</strong> to point out the financial advantages of a course of action</span></label></div></div><div class="ielts-standalone-q" data-qnum="17"><div class="ielts-q-header"><strong class="ielts-q-badge">17</strong><span class="ielts-q-title"><span>What challenge does the writer refer to in the fourth paragraph?</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="17" name="question_17" value="A"><span class="ielts-radio-text"><strong>A</strong> encouraging humans to behave in a more principled way</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="17" name="question_17" value="B"><span class="ielts-radio-text"><strong>B</strong> deciding which values we want AI to share with us</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="17" name="question_17" value="C"><span class="ielts-radio-text"><strong>C</strong> creating a better world for all creatures on the planet</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="17" name="question_17" value="D"><span class="ielts-radio-text"><strong>D</strong> ensuring AI is more human-friendly than we are ourselves</span></label></div></div><div class="ielts-standalone-q" data-qnum="18"><div class="ielts-q-header"><strong class="ielts-q-badge">18</strong><span class="ielts-q-title"><span>What does the writer suggest about the future of AI in the fifth paragraph?</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="18" name="question_18" value="A"><span class="ielts-radio-text"><strong>A</strong> The safety of machines will become a key issue.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="18" name="question_18" value="B"><span class="ielts-radio-text"><strong>B</strong> It is hard to know what impact machines will have on the world.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="18" name="question_18" value="C"><span class="ielts-radio-text"><strong>C</strong> Machines will be superior to humans in certain respects.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="18" name="question_18" value="D"><span class="ielts-radio-text"><strong>D</strong> Many humans will oppose machines having a wider role.</span></label></div></div><div class="ielts-standalone-q" data-qnum="19"><div class="ielts-q-header"><strong class="ielts-q-badge">19</strong><span class="ielts-q-title"><span>Which of the following best summarises the writer’s argument in the sixth paragraph?</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="19" name="question_19" value="A"><span class="ielts-radio-text"><strong>A</strong> More intelligent machines will result in greater abuses of power.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="19" name="question_19" value="B"><span class="ielts-radio-text"><strong>B</strong> Machine learning will share very few features with human learning.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="19" name="question_19" value="C"><span class="ielts-radio-text"><strong>C</strong> There are a limited number of people with the knowledge to program machines.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="19" name="question_19" value="D"><span class="ielts-radio-text"><strong>D</strong> Human shortcomings will make creating the machines we need more difficult.</span></label></div></div></div>
                                                                                                                                    </div>
                                                                                                                                                            <h2 class="ielts-reading-question-section-heading">
                                            Questions 20-23                                                                                                                                                
                                                                                                                                    </h2>
                                        <div class="ielts-reading-question-section-content">
                                            <p>Do the following statements agree with the claims of the writer in The Reading Passage?</p>
<p><em>In boxes on your answer sheet, write</em></p>
<p><strong><em>YES</em></strong><em>               if the statement agrees with the claims of the writer</em></p>
<p><strong><em>NO</em></strong><em>                if the statement contradicts the claims of the writer</em></p>
<p><strong><em>NOT</em></strong><em> <strong>GIVEN</strong>  if it is impossible to say what the writer thinks about this</em></p>
                                        </div>
                                        <div class="ielts-reading-questions">
