-- Section 1833: Reading Passage 3: The case for mixed-ability classes
INSERT INTO sections (id, test_id, type, title, instructions, audio_url, passage_text, order_index) VALUES
(1833, 183, 'reading', 'Reading Passage 3: The case for mixed-ability classes', '<div class="ielts-reading-container"><h2 class="ielts-reading-question-section-heading">
                                            Questions 27-30                                                                                                                                                
                                                                                                                                    </h2>
                                        <div class="ielts-reading-question-section-content">
                                            <p><em>Choose the correct letter, <strong>A</strong>, <strong>B</strong>, <strong>C</strong> or <strong>D</strong>.</em></p>
<p><em>Write the correct letter in boxes on your answer sheet.</em></p>
                                        </div>
                                        <div class="ielts-reading-questions">
                                                                                                                                                                                            <div class="ielts-standalone-q" data-qnum="27"><div class="ielts-q-header"><strong class="ielts-q-badge">27</strong><span class="ielts-q-title"><span>The writer describes the <em>Romeo and Juliet</em> lesson in order to demonstrate</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="27" name="question_27" value="A"><span class="ielts-radio-text"><strong>A</strong> how few students are interested in literature.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="27" name="question_27" value="B"><span class="ielts-radio-text"><strong>B</strong> how a teacher handles a range of learning needs.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="27" name="question_27" value="C"><span class="ielts-radio-text"><strong>C</strong> how unsuitable Shakespeare is for most teenagers.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="27" name="question_27" value="D"><span class="ielts-radio-text"><strong>D</strong> how weaker students can disrupt their classmates’ learning.</span></label></div></div><div class="ielts-standalone-q" data-qnum="28"><div class="ielts-q-header"><strong class="ielts-q-badge">28</strong><span class="ielts-q-title"><span>What does the writer say about streaming in the third paragraph?</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="28" name="question_28" value="A"><span class="ielts-radio-text"><strong>A</strong> It has a very broad appeal.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="28" name="question_28" value="B"><span class="ielts-radio-text"><strong>B</strong> It favours cleverer students.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="28" name="question_28" value="C"><span class="ielts-radio-text"><strong>C</strong> It is relatively simple to implement.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="28" name="question_28" value="D"><span class="ielts-radio-text"><strong>D</strong> It works better in some schools than others.</span></label></div></div><div class="ielts-standalone-q" data-qnum="29"><div class="ielts-q-header"><strong class="ielts-q-badge">29</strong><span class="ielts-q-title"><span>What idea is suggested by the reference to Mount Qomolangma in the fifth paragraph?</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="29" name="question_29" value="A"><span class="ielts-radio-text"><strong>A</strong> students following unsuitable paths</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="29" name="question_29" value="B"><span class="ielts-radio-text"><strong>B</strong> students attempting interesting tasks</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="29" name="question_29" value="C"><span class="ielts-radio-text"><strong>C</strong> students not achieving their full potential</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="29" name="question_29" value="D"><span class="ielts-radio-text"><strong>D</strong> students not being aware of their limitations</span></label></div></div><div class="ielts-standalone-q" data-qnum="30"><div class="ielts-q-header"><strong class="ielts-q-badge">30</strong><span class="ielts-q-title"><span>What does the word ‘scaffolding’ in the sixth paragraph refer to?</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="30" name="question_30" value="A"><span class="ielts-radio-text"><strong>A</strong> the factors which prevent a student from learning effectively</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="30" name="question_30" value="B"><span class="ielts-radio-text"><strong>B</strong> the environment where most of a student’s learning takes place</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="30" name="question_30" value="C"><span class="ielts-radio-text"><strong>C</strong> the assistance given to a student in their initial stages of learning</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="30" name="question_30" value="D"><span class="ielts-radio-text"><strong>D</strong> the setting of appropriate learning targets for a student’s aptitude</span></label></div></div></div>
                                                                                                                                    </div>
                                                                                                                                                            <h2 class="ielts-reading-question-section-heading">
                                            Questions 31-35                                                                                                                                                
                                                                                                                                    </h2>
                                        <div class="ielts-reading-question-section-content">
                                            <div class="ielts-reading-section-content-wrapper"><p><em>Complete the summary using the list of phrases, <strong>A-l</strong>, below.</em></p>
<p><em>Write the correct letter, <strong>A-l</strong>, in boxes on your answer sheet.</em></p>
<p class="ielts-reading-passage-subhead"><strong><strong>Is streaming effective?</strong></strong></p>
<p>According to Professor John Hattie of the Melbourne Education Research Institute there is very little indication that streaming leads to <span class="ielts-reading-question-item"><span class="ielts-inline-select-wrap"><strong class="ielts-q-badge">31</strong><select data-qnum="31" name="question_31" class="ielts-inline-select"><option value="">[ 31 ] Tanlang...</option><option value="A. wrong classes">A. wrong classes</option><option value="B. lower expectations">B. lower expectations</option><option value="C. average learners">C. average learners</option><option value="D. bottom sets">D. bottom sets</option><option value="E. brightest pupils">E. brightest pupils</option><option value="F. disadvantaged backgrounds">F. disadvantaged backgrounds</option><option value="G. weaker students">G. weaker students</option><option value="H. higher achievements">H. higher achievements</option><option value="I. positive impressions">I. positive impressions</option></select></span></span>. He points out that, in schools which use streaming, the most significant impact is on those students placed in the <span class="ielts-reading-question-item"><span class="ielts-inline-select-wrap"><strong class="ielts-q-badge">32</strong><select data-qnum="32" name="question_32" class="ielts-inline-select"><option value="">[ 32 ] Tanlang...</option><option value="A. wrong classes">A. wrong classes</option><option value="B. lower expectations">B. lower expectations</option><option value="C. average learners">C. average learners</option><option value="D. bottom sets">D. bottom sets</option><option value="E. brightest pupils">E. brightest pupils</option><option value="F. disadvantaged backgrounds">F. disadvantaged backgrounds</option><option value="G. weaker students">G. weaker students</option><option value="H. higher achievements">H. higher achievements</option><option value="I. positive impressions">I. positive impressions</option></select></span></span>, especially where a large proportion of them have <span class="ielts-reading-question-item"><span class="ielts-inline-select-wrap"><strong class="ielts-q-badge">33</strong><select data-qnum="33" name="question_33" class="ielts-inline-select"><option value="">[ 33 ] Tanlang...</option><option value="A. wrong classes">A. wrong classes</option><option value="B. lower expectations">B. lower expectations</option><option value="C. average learners">C. average learners</option><option value="D. bottom sets">D. bottom sets</option><option value="E. brightest pupils">E. brightest pupils</option><option value="F. disadvantaged backgrounds">F. disadvantaged backgrounds</option><option value="G. weaker students">G. weaker students</option><option value="H. higher achievements">H. higher achievements</option><option value="I. positive impressions">I. positive impressions</option></select></span></span>. Meanwhile, for the <span class="ielts-reading-question-item"><span class="ielts-inline-select-wrap"><strong class="ielts-q-badge">34</strong><select data-qnum="34" name="question_34" class="ielts-inline-select"><option value="">[ 34 ] Tanlang...</option><option value="A. wrong classes">A. wrong classes</option><option value="B. lower expectations">B. lower expectations</option><option value="C. average learners">C. average learners</option><option value="D. bottom sets">D. bottom sets</option><option value="E. brightest pupils">E. brightest pupils</option><option value="F. disadvantaged backgrounds">F. disadvantaged backgrounds</option><option value="G. weaker students">G. weaker students</option><option value="H. higher achievements">H. higher achievements</option><option value="I. positive impressions">I. positive impressions</option></select></span></span>, there appears to be only minimal advantage. A further issue is that teachers tend to have <span class="ielts-reading-question-item"><span class="ielts-inline-select-wrap"><strong class="ielts-q-badge">35</strong><select data-qnum="35" name="question_35" class="ielts-inline-select"><option value="">[ 35 ] Tanlang...</option><option value="A. wrong classes">A. wrong classes</option><option value="B. lower expectations">B. lower expectations</option><option value="C. average learners">C. average learners</option><option value="D. bottom sets">D. bottom sets</option><option value="E. brightest pupils">E. brightest pupils</option><option value="F. disadvantaged backgrounds">F. disadvantaged backgrounds</option><option value="G. weaker students">G. weaker students</option><option value="H. higher achievements">H. higher achievements</option><option value="I. positive impressions">I. positive impressions</option></select></span></span> of students in streamed groups.</p>
