-- Section 1841: Reading Passage 1: Green roofs
INSERT INTO sections (id, test_id, type, title, instructions, audio_url, passage_text, order_index) VALUES
(1841, 184, 'reading', 'Reading Passage 1: Green roofs', '<div class="ielts-reading-container"><h2 class="ielts-reading-question-section-heading">
                                            Questions 1-5                                                                                                                                                                                                    
                                                                                                                                    </h2>
                                        <div class="ielts-reading-question-section-content">
                                            <p>The Reading Passage has five paragraphs, <strong>A-E</strong>.</p>
<p>Which paragraph contains the following information?</p>
<p><em>Write the correct letter, <strong>A-E</strong>, in boxes on your answer sheet.</em></p>
<p><strong><em>NB</em></strong><em>   You may use any letter more than once.</em></p>
                                        </div>
                                        <div class="ielts-reading-questions">
                                                                                                                                                                                                <table class="ielts-reading-matching-table"><thead><tr><th></th><th>A</th><th>B</th><th>C</th><th>D</th><th>E</th></tr></thead><tbody><tr class="ielts-reading-question-item"><td class="ielts-reading-matching-question-cell"><strong id="ielts-reading-question-number-1" class="ielts-q-badge">1</strong> <span>mention of several challenges to be overcome before a green roof can be installed</span></td>
