-- Section 1842: Reading Passage 2: The growth mindset
INSERT INTO sections (id, test_id, type, title, instructions, audio_url, passage_text, order_index) VALUES
(1842, 184, 'reading', 'Reading Passage 2: The growth mindset', '<div class="ielts-reading-container"><h2 class="ielts-reading-question-section-heading">
                                            Questions 14-16                                                                                                                                                
                                                                                                                                    </h2>
                                        <div class="ielts-reading-question-section-content">
                                            <p><em>Choose the correct letter, <strong>A</strong>, <strong>B</strong>, <strong>C</strong> or <strong>D</strong>.</em></p>
<p><em>Write the correct letter in boxes on your answer sheet</em></p>
                                        </div>
                                        <div class="ielts-reading-questions">
                                                                                                                                                                                            <div class="ielts-standalone-q" data-qnum="14"><div class="ielts-q-header"><strong class="ielts-q-badge">14</strong><span class="ielts-q-title"><span>What can we learn from the first paragraph?</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="14" name="question_14" value="A"><span class="ielts-radio-text"><strong>A</strong> where the notion of innate intelligence first began</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="14" name="question_14" value="B"><span class="ielts-radio-text"><strong>B</strong> when ideas about the nature of intelligence began to shift</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="14" name="question_14" value="C"><span class="ielts-radio-text"><strong>C</strong> how scientists have responded to changing views of intelligence</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="14" name="question_14" value="D"><span class="ielts-radio-text"><strong>D</strong> why thinkers turned away from the idea of intelligence being fixed</span></label></div></div><div class="ielts-standalone-q" data-qnum="15"><div class="ielts-q-header"><strong class="ielts-q-badge">15</strong><span class="ielts-q-title"><span>The second paragraph describes how schools encourage students to</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="15" name="question_15" value="A"><span class="ielts-radio-text"><strong>A</strong> identify their personal ambitions.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="15" name="question_15" value="B"><span class="ielts-radio-text"><strong>B</strong> help each other to realise their goals.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="15" name="question_15" value="C"><span class="ielts-radio-text"><strong>C</strong> have confidence in their potential to succeed.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="15" name="question_15" value="D"><span class="ielts-radio-text"><strong>D</strong> concentrate on where their particular strengths lie.</span></label></div></div><div class="ielts-standalone-q" data-qnum="16"><div class="ielts-q-header"><strong class="ielts-q-badge">16</strong><span class="ielts-q-title"><span>In the third paragraph, the writer suggests that students with a fixed mindset</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="16" name="question_16" value="A"><span class="ielts-radio-text"><strong>A</strong> tend to be less competitive.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="16" name="question_16" value="B"><span class="ielts-radio-text"><strong>B</strong> generally have a low sense of self-esteem.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="16" name="question_16" value="C"><span class="ielts-radio-text"><strong>C</strong> will only work hard if they are given constant encouragement.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="16" name="question_16" value="D"><span class="ielts-radio-text"><strong>D</strong> are afraid to push themselves beyond what they see as their limitations.</span></label></div></div></div>
                                                                                                                                    </div>
                                                                                                                                                            <h2 class="ielts-reading-question-section-heading">
                                            Questions 17-22                                                                                                                                                
                                                                                                                                    </h2>
                                        <div class="ielts-reading-question-section-content">
                                            <p><em>Look at the following statements and the list of people below.</em></p>
<p><em>Match each statement with the correct person or people, <strong>A-E</strong>.</em></p>
<p><em>Write the correct letter, <strong>A-E</strong>, in boxes on your answer sheet.</em></p>
<p><strong><em>NB</em></strong><em>   You may use any letter more than once.</em></p>
<p><strong>List of People</strong></p>
<p><strong>A  </strong> Alfred Binet</p>
