INSERT INTO sections (id, test_id, type, title, instructions, audio_url, passage_text, order_index) VALUES
(1843, 184, 'reading', 'Reading Passage 3: Alfred Wegener: science, exploration and the theory of continental drift', '<div class="ielts-reading-container"><h2 class="ielts-reading-question-section-heading">
